        InterviewCapture: {
            text: string;
        };
        InterviewSuggestedAnswers: {
            trigger: string;
            mustKnow: string;
            steps: string;
            goesWrong: string;
            notDecide: string;
            closing: string;
            /** @description What the author says must never happen (FU-07). */
            neverDo: string;
        };
