                    protocolMode?: components["schemas"]["MCPProtocolMode"];
                    /** @description Bearer token for a remote server. Omit to keep the stored one — correcting a URL must not demand re-entering a secret nobody has to hand. */
                    token?: string;
                    /** @description Exact HTTP headers for a remote server whose credential is not a bearer token, such as Api-Key or Authorization: Basic. Omit to keep stored headers. Send an empty object to remove them. A non-empty object becomes the active HTTP credential and replaces stored bearer or OAuth material. */
                    headers?: {
                        [key: string]: string;
                    };
                    /** @description OAuth grant for a remote server. Omit to keep the stored grant. Send an empty object to clear it. A non-empty grant becomes the active HTTP credential and replaces a stored bearer token. */
                    oauth?: components["schemas"]["MCPOAuthGrant"];
                    /**
                     * @description Variables handed to a local server, and only to one. A program started inside the worker no longer inherits the worker's environment, so this is how it receives the credential it needs — explicitly, per server, from the vault.
                     *     Sealed like the token, because the reason a server needs a variable is nearly always that the variable is a key, and a field that is sometimes a secret is stored as one always.
                     *     Omit to keep what is stored. Send an empty object to clear it: not sending something and sending nothing are different requests, and only one of them can be an erasure.
                     */
                    env?: {
                        [key: string]: string;
                    };
                    /** @description Configuration content to seal and materialise as a file for a local server. Omit to keep the stored file. Send an empty string to remove it. */
                    configFile?: string;
                    /** @description Environment variable that receives the managed file path. Omit to keep the stored variable; send an empty string to use the platform default. Meaningless for http. */
                    configFileEnv?: string;
                    /** @description Which of the server's tools to bring in, by the names the server uses. Omit to leave the choice as it stands, which for a server nobody has chosen one for means everything it offers. Send an empty array to bring in nothing. */
                    surface?: string[];
                    /** @description Per-worker token bucket for outgoing tool calls to this server. Omit to leave the choice as it stands. Send both fields as zero to disable it. */
                    rateLimit?: components["schemas"]["MCPRateLimit"];
                    /** @description Per-worker in-memory cache for successful read-only tool results from this server. Omit to leave the choice as it stands. Send both fields as zero to disable it. */
                    cache?: components["schemas"]["MCPResultCache"];
                    /** @description Egress request for a local stdio process. Omit to leave the stored choice as it stands. Send mode inherit to clear it. Send mode proxied with destinations to require a worker egress proxy before the process starts. The proxy environment is not, by itself, network containment; a deployment-level egress policy is still the enforcement boundary. */
                    stdioEgress?: components["schemas"]["MCPStdioEgress"];
                    /** @description Required for stdio, and refused without it. A local server is a program this installation starts inside the worker, running as the worker and reaching whatever the worker can reach. That is a decision a person makes, not one a transport implies, and it is recorded with their name. */
                    acceptsLocalExecution?: boolean;
